//! ModelCall controls — generated by tidepool-protocol.
#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
pub enum ModelEffortEnvelope {
    #[serde(rename = "low")]
    ModelLowEffort,
    #[serde(rename = "medium")]
    ModelMediumEffort,
    #[serde(rename = "high")]
    ModelHighEffort,
}

#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
pub enum ModelLimitEnvelope {
    #[serde(rename = "requests")]
    ModelRequestsLimit,
    #[serde(rename = "tools")]
    ModelToolsLimit,
    #[serde(rename = "reported_tokens")]
    ModelTokensLimit,
    #[serde(rename = "deadline")]
    ModelDeadlineLimit,
}

#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ModelRequestLimits {
    pub requests: Option<u64>,
    pub tools: Option<u64>,
    pub reported_tokens: Option<u64>,
    pub seconds: Option<u64>,
}

#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ModelRequestEnvelope {
    pub instructions: String,
    pub input: String,
    pub model: Option<String>,
    pub effort: Option<ModelEffortEnvelope>,
    pub limits: ModelRequestLimits,
    pub tools: Vec<exomonad_tool::ToolDeclaration>,
    pub result_schema: Option<serde_json::Value>,
    pub after_tool: bool,
}

#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ModelUsageEnvelope {
    pub requests: u64,
    pub tools: u64,
    pub reported_tokens: u64,
    pub unknown_usage_requests: u64,
}

#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "kind", deny_unknown_fields)]
pub enum ModelOutcomeEnvelope {
    #[serde(rename = "text")]
    ModelTextOutcome { value: String },
    #[serde(rename = "typed")]
    ModelTypedOutcome { value: serde_json::Value },
    #[serde(rename = "failed")]
    ModelFailedOutcome { value: String },
    #[serde(rename = "cancelled")]
    ModelCancelledOutcome,
    #[serde(rename = "exhausted")]
    ModelExhaustedOutcome { value: ModelLimitEnvelope },
}

#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ModelReceiptEnvelope {
    pub invocation_id: String,
    pub parent_cell: String,
    pub requests: Vec<String>,
    pub counts: ModelUsageEnvelope,
    pub cell_counts: ModelUsageEnvelope,
    pub outcome: ModelOutcomeEnvelope,
}

#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "kind", deny_unknown_fields)]
pub enum ModelControlStep {
    #[serde(rename = "callback")]
    ModelCallback {
        invocation: String,
        call_id: String,
        name: String,
        arguments: serde_json::Value,
    },
    #[serde(rename = "hook")]
    ModelHook {
        invocation: String,
        operation: String,
        name: String,
        arguments: serde_json::Value,
        handle: String,
        ordinal: i64,
        value: serde_json::Value,
        output: String,
    },
    #[serde(rename = "finished")]
    ModelFinished { receipt: ModelReceiptEnvelope },
}

#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "kind", deny_unknown_fields)]
pub enum ModelAnnotationEnvelope {
    #[serde(rename = "none")]
    ModelNoAnnotation,
    #[serde(rename = "abstained")]
    ModelAbstained { reason: String },
    #[serde(rename = "annotated")]
    ModelAnnotated { text: String },
    #[serde(rename = "pruned")]
    ModelPruned { handle: String, text: String },
}
